#!/bin/bash
# Generated by scripts/build-operations-installer.py; edit starter/ and rebuild.
# Stock macOS Bash 3.2; no Python or Git runtime required.
# Download completely and check curl succeeds before executing this script.
# Piped stdin is supported; the script cannot verify an upstream curl exit code.
main() {
    set -euo pipefail
    local destination="${HOME:?HOME must be set}/Documents/AI Operations"
    local no_open=0 with_mangomagic=0 no_restart=0 created=0 preserved=0

    fail() { printf 'Setup stopped: %s\n' "$*" >&2; exit 1; }
    usage() {
        cat <<'OPERATIONS_USAGE'
Create a local AI Operations starter folder. Existing files are preserved.

Usage: /bin/bash setup-operations.sh [--destination PATH] [--no-open]
                                   [--with-mangomagic [--no-restart]]
       /bin/bash -s -- [options] < downloaded-setup.sh

  --destination PATH  Folder to populate (default: $HOME/Documents/AI Operations).
  --no-open           Do not open the folder in Finder.
  --with-mangomagic   Also install MangoMagic 7.1, register it and restart ChatGPT.
  --no-restart        With --with-mangomagic, defer the ChatGPT restart.
  --help              Show this help without making changes.

Without --with-mangomagic this creates local files only. Add the folder as a
local project in the app, then paste the onboarding prompt from START_HERE.md
into a new task in that project.
OPERATIONS_USAGE
    }
    while [ "$#" -gt 0 ]; do
        case "$1" in
            --destination)
                [ "$#" -ge 2 ] || fail '--destination requires a path.'
                [ -n "$2" ] || fail '--destination requires a non-empty path.'
                case "$2" in --*) fail '--destination requires a path, not an option.' ;; esac
                destination=$2; shift 2 ;;
            --no-open) no_open=1; shift ;;
            --with-mangomagic) with_mangomagic=1; shift ;;
            --no-restart) no_restart=1; shift ;;
            --help) usage; return 0 ;;
            *) fail "Unknown option: $1 (use --help)." ;;
        esac
    done
    local gold='' bold='' reset=''
    if [ -t 1 ] && [ -z "${NO_COLOR+x}" ]; then
        gold=$'\033[38;5;214m'; bold=$'\033[1m'; reset=$'\033[0m'
    fi
    printf '\n%s  +--------------------------------------------------+%s\n' "$gold" "$reset"
    printf '%s%s    ManyMangoes%s\n' "$gold" "$bold" "$reset"
    printf '    Data + AI + Automation\n'
    printf '    AI Operations | Your local workspace\n'
    printf '%s  +--------------------------------------------------+%s\n\n' "$gold" "$reset"
    case "$destination" in /*) ;; *) destination="$PWD/$destination" ;; esac
    # Strip trailing slashes and /., which otherwise hide a symlink root.
    while [ "$destination" != / ]; do
        case "$destination" in
            */) destination=${destination%/} ;;
            */.) destination=${destination%/.} ;;
            *) break ;;
        esac
    done

    check_directory() {
        local path=$1
        [ ! -L "$path" ] || fail "Symlink directory refused: $path"
        if [ -e "$path" ] && [ ! -d "$path" ]; then
            fail "Not a directory: $path"
        fi
    }
    check_parents() {
        local relative=$1 path="$destination" component
        check_directory "$path"
        while [ -n "$relative" ]; do
            component=${relative%%/*}
            path="$path/$component"
            check_directory "$path"
            case "$relative" in */*) relative=${relative#*/} ;; *) break ;; esac
        done
    }
    check_file() {
        local relative=$1 path="$destination/$1"
        case "$relative" in */*) check_parents "${relative%/*}" ;; *) check_parents '' ;; esac
        [ ! -L "$path" ] || fail "Symlink file refused: $path"
        if [ -e "$path" ] && [ ! -f "$path" ]; then
            fail "Not a regular file: $path"
        fi
    }
    ensure_directory() {
        check_parents "$1"
        mkdir -p -- "$destination/$1" || fail "Cannot create directory: $destination/$1"
    }
    write_file() {
        local relative=$1 executable=$2 final_newline=$3
        local path="$destination/$1"
        check_file "$relative"
        if [ -f "$path" ]; then
            preserved=$((preserved + 1))
            return 0
        fi
        # Quoted heredocs supply literal data. The loop also preserves files
        # lacking a final newline, without eval or command substitution.
        # Stage on the same filesystem. Only a complete, permissioned file is
        # published. Stock macOS link uses the exact target (unlike ln, which
        # can put the file INSIDE a raced directory), and never overwrites it.
        if ! (
            temporary=''
            cleanup_temp() {
                local status=$?
                trap - EXIT
                if [ -n "$temporary" ]; then
                    if ! rm -f -- "$temporary"; then
                        printf 'Cannot remove temporary file: %s\n' "$temporary" >&2
                        [ "$status" -ne 0 ] || status=1
                    fi
                fi
                exit "$status"
            }
            trap cleanup_temp EXIT
            trap 'exit 130' INT
            trap 'exit 143' TERM
            temporary=$(mktemp "${path%/*}/.operations-setup.XXXXXXXX") || exit 1
            emit_text() {
                local line first=1
                while IFS= read -r line; do
                    if [ "$first" -eq 0 ]; then printf '\n' || return 1; fi
                    printf '%s' "$line" || return 1
                    first=0
                done
                if [ "$final_newline" -eq 1 ]; then printf '\n' || return 1; fi
                return 0
            }
            emit_text > "$temporary" || exit 1
            if [ "$executable" -eq 1 ]; then
                chmod 755 "$temporary" || exit 1
            else
                chmod 644 "$temporary" || exit 1
            fi
            check_file "$relative"
            [ ! -e "$path" ] || fail "Destination appeared during setup: $path"
            link "$temporary" "$path" || exit 1
        ); then
            fail "Cannot create file: $path"
        fi
        created=$((created + 1))
    }

    # Keep the EXIT trap and its download variable alive in the same scope,
    # without replacing the caller's traps or leaving cleanup until main exits.
    install_mangomagic() (
        local f=''
        cleanup_download() {
            local status=$?
            trap - EXIT
            if [ -n "$f" ]; then
                if ! rm -f -- "$f"; then
                    printf 'Cannot remove MangoMagic download: %s\n' "$f" >&2
                    [ "$status" -ne 0 ] || status=1
                fi
            fi
            exit "$status"
        }
        trap cleanup_download EXIT
        trap 'exit 130' INT
        trap 'exit 143' TERM
        command -v curl >/dev/null 2>&1 || fail 'MangoMagic setup needs curl.'
        f=$(mktemp "${TMPDIR:-/tmp}/mangomagic-install.XXXXXXXX") || fail 'Cannot create a temporary file.'
        if ! curl -fsSL https://raw.githubusercontent.com/mango-magic/mangomagic/main/install.sh -o "$f"; then
            fail 'Could not download the MangoMagic installer.'
        fi
        if [ "$no_restart" -eq 1 ]; then
            /bin/bash "$f" --no-restart || fail 'MangoMagic setup failed.'
        else
            /bin/bash "$f" || fail 'MangoMagic setup failed.'
        fi
    )

    # Validate the entire manifest before creating directories or files.
    check_directory "$destination"
    check_file .codex/agents/automation.toml
    check_file .codex/agents/chief-of-staff.toml
    check_file .codex/agents/content.toml
    check_file .codex/agents/quality.toml
    check_file .codex/agents/research.toml
    check_file .codex/agents/sales.toml
    check_file .gitignore
    check_file 00_Command_Centre/ASSISTANT_PROFILE.md
    check_file 00_Command_Centre/ASSISTANT_ROLLOUT.md
    check_file 00_Command_Centre/BUILD_MY_ASSISTANT.md
    check_file 00_Command_Centre/BUSINESS_BRIEF.md
    check_file 00_Command_Centre/HANDOFF.md
    check_file 00_Command_Centre/TASK_BRIEF.md
    check_file 01_Data/README.md
    check_file 01_Data/SOURCE_REGISTER.csv
    check_file 01_Data/sanitised-conversations/README.md
    check_file 01_Data/source-documents/README.md
    check_file 02_Agents/AGENT_ROSTER.md
    check_file 02_Agents/ROLE_TEMPLATE.md
    check_file 02_Agents/automation/AGENTS.md
    check_file 02_Agents/automation/working/README.md
    check_file 02_Agents/chief-of-staff/AGENTS.md
    check_file 02_Agents/chief-of-staff/working/README.md
    check_file 02_Agents/content/AGENTS.md
    check_file 02_Agents/content/working/README.md
    check_file 02_Agents/quality/AGENTS.md
    check_file 02_Agents/quality/working/README.md
    check_file 02_Agents/research/AGENTS.md
    check_file 02_Agents/research/working/README.md
    check_file 02_Agents/sales/AGENTS.md
    check_file 02_Agents/sales/working/README.md
    check_file 03_Projects/README.md
    check_file 03_Projects/project-template/TASK_BRIEF.md
    check_file 03_Projects/project-template/project_tasks.json
    check_file 04_Automations/AUTOMATION_BRIEF.md
    check_file 04_Automations/README.md
    check_file 05_Deliverables/README.md
    check_file AGENTS.md
    check_file CURRENT_MISSION.md
    check_file START_HERE.md
    check_file project_tasks.json
    ensure_directory ''
    ensure_directory .codex
    ensure_directory 00_Command_Centre
    ensure_directory 01_Data
    ensure_directory 02_Agents
    ensure_directory 03_Projects
    ensure_directory 04_Automations
    ensure_directory 05_Deliverables
    ensure_directory .codex/agents
    ensure_directory 01_Data/sanitised-conversations
    ensure_directory 01_Data/source-documents
    ensure_directory 02_Agents/automation
    ensure_directory 02_Agents/chief-of-staff
    ensure_directory 02_Agents/content
    ensure_directory 02_Agents/quality
    ensure_directory 02_Agents/research
    ensure_directory 02_Agents/sales
    ensure_directory 03_Projects/project-template
    ensure_directory 02_Agents/automation/working
    ensure_directory 02_Agents/chief-of-staff/working
    ensure_directory 02_Agents/content/working
    ensure_directory 02_Agents/quality/working
